part of 'academy_english_advanced_models.dart';

/// A second, separately authored lesson at each level.
abstract final class EnglishAdvancedSecondLessons {
  static const lessons = <EnglishAdvancedLesson>[
    EnglishAdvancedLesson(level:"A2", number:2, title:"The Baker's Early Morning", titleArabic:"صباح الخبّاز", storyTitle:"The Baker's Early Morning", storyTitleArabic:"صباح الخبّاز", paragraphs:<String>["Before sunrise, Nora entered the bakery and put on her apron. Her father was mixing flour with water to make dough, while the oven was slowly becoming warm. Nora followed the recipe carefully because they wanted to prepare fresh bread for the morning.","At eight o'clock, the first customer arrived and asked for a loaf and a sweet roll. Nora wrapped the bread, counted the coins and gave the customer the correct change. The customer smiled and said the smell of warm bread made the street feel friendly.","By noon, the shelves were nearly empty. Nora cleaned the counter and helped prepare another batch for the afternoon. She felt tired but pleased: this was the first day she had managed the small shop without making a mistake."], storyWords:<EnglishAdvancedWord>[EnglishAdvancedWord("bakery","مخبز"),EnglishAdvancedWord("apron","مئزر"),EnglishAdvancedWord("flour","طحين"),EnglishAdvancedWord("dough","عجين"),EnglishAdvancedWord("oven","فرن"),EnglishAdvancedWord("recipe","وصفة"),EnglishAdvancedWord("bread","خبز"),EnglishAdvancedWord("customer","زبون"),EnglishAdvancedWord("loaf","رغيف"),EnglishAdvancedWord("coins","عملات معدنية")], extraWords:<EnglishAdvancedWord>[EnglishAdvancedWord("yeast","خميرة"),EnglishAdvancedWord("crust","قشرة الخبز"),EnglishAdvancedWord("pastry","معجنات"),EnglishAdvancedWord("knead","يعجن"),EnglishAdvancedWord("baking tray","صينية خبز"),EnglishAdvancedWord("counter","منضدة بيع"),EnglishAdvancedWord("shelves","رفوف"),EnglishAdvancedWord("batch","دفعة"),EnglishAdvancedWord("ingredient","مكون"),EnglishAdvancedWord("cashier","أمين صندوق"),EnglishAdvancedWord("slice","شريحة"),EnglishAdvancedWord("freshly baked","مخبوز طازج"),EnglishAdvancedWord("daily special","عرض اليوم"),EnglishAdvancedWord("takeaway","طلب خارجي")], grammarTitle:"Countable and uncountable nouns", grammarArabic:"في A2 نتعلم الفرق بين المعدود وغير المعدود: one loaf / two loaves لكن some flour وsome bread. نستخدم How many للرغيف وHow much للطحين. انتبه أن bread عادة غير معدود.", grammarExamples:<String>["How much flour do we need?","There are three loaves on the shelf.","Could I have some bread, please?"], listening:"Good morning, and welcome to Nora's bakery. Today's special is a freshly baked loaf with a free sweet roll. We will close at three this afternoon because the oven needs cleaning. If you would like to collect an order after lunchtime, please telephone us before eleven. We have plenty of bread this morning, but there are only six chocolate pastries left.", listeningQuestion:"Why will the bakery close early today?", listeningOptions:<String>["The oven needs cleaning","All workers are on holiday","The shop has no flour"], listeningAnswer:0, readingQuestion:"What did Nora do when the customer bought bread?", readingOptions:<String>["She gave correct change","She closed the bakery","She went to the market"], readingAnswer:0, writingCue:"Nora wore an ____ while making bread.", writingAnswer:"apron"),
    EnglishAdvancedLesson(level:"B1", number:2, title:"The Riverside Festival", titleArabic:"مهرجان ضفاف النهر", storyTitle:"The Riverside Festival", storyTitleArabic:"مهرجان ضفاف النهر", paragraphs:<String>["The annual festival usually filled the riverside with music, crafts and families. This year, a young coordinator called Tessa wanted to make the event more welcoming. She invited a local choir and arranged a rehearsal at the open-air stage.","Several performers were enthusiastic, but a technical problem threatened the opening show. One microphone stopped working, and the sound engineer could not replace it immediately. The audience began to gather while volunteers searched for a spare cable.","Tessa made an announcement and asked visitors to explore the craft stalls. An elderly musician offered an acoustic performance without electronic equipment. The informal show delighted the crowd and created a warm atmosphere that nobody had planned.","When the main concert finally began, many spectators said they had enjoyed both performances. Tessa learned that a successful celebration required preparation, but also adaptability. The unexpected delay had brought strangers together rather than sending them home."], storyWords:<EnglishAdvancedWord>[EnglishAdvancedWord("festival","مهرجان"),EnglishAdvancedWord("riverside","ضفة النهر"),EnglishAdvancedWord("coordinator","منسق"),EnglishAdvancedWord("choir","جوقة غناء"),EnglishAdvancedWord("rehearsal","بروفة"),EnglishAdvancedWord("stage","خشبة المسرح"),EnglishAdvancedWord("performers","مؤدون"),EnglishAdvancedWord("microphone","ميكروفون"),EnglishAdvancedWord("sound engineer","مهندس صوت"),EnglishAdvancedWord("audience","جمهور"),EnglishAdvancedWord("announcement","إعلان"),EnglishAdvancedWord("atmosphere","أجواء")], extraWords:<EnglishAdvancedWord>[EnglishAdvancedWord("acoustic performance","عرض موسيقي دون كهرباء"),EnglishAdvancedWord("spectators","متفرجون"),EnglishAdvancedWord("craft stalls","أكشاك الحرف"),EnglishAdvancedWord("musical equipment","معدات موسيقية"),EnglishAdvancedWord("setlist","قائمة الأغاني"),EnglishAdvancedWord("soundcheck","فحص الصوت"),EnglishAdvancedWord("backup plan","خطة بديلة"),EnglishAdvancedWord("curtain call","تحية الختام"),EnglishAdvancedWord("stage lighting","إضاءة المسرح"),EnglishAdvancedWord("master of ceremonies","مقدم الحفل"),EnglishAdvancedWord("festival grounds","ساحة المهرجان"),EnglishAdvancedWord("performing arts","فنون أداء"),EnglishAdvancedWord("improvisation","ارتجال"),EnglishAdvancedWord("appreciation","تقدير"),EnglishAdvancedWord("community spirit","روح المجتمع"),EnglishAdvancedWord("entrance fee","رسوم دخول"),EnglishAdvancedWord("crowd control","تنظيم الحشود"),EnglishAdvancedWord("encore","إعادة أداء")], grammarTitle:"Narrative tenses: past perfect", grammarArabic:"يُستخدم الماضي التام لإظهار أن حدثًا وقع قبل حدث آخر في الماضي: The audience had arrived before the concert began. الصيغة had + past participle، ويمكن دمجه مع الماضي البسيط لسرد قصص واضحة.", grammarExamples:<String>["The crowd had gathered before the show started.","She had prepared a backup plan.","After they had fixed the sound, the concert began."], listening:"Welcome to the Riverside Festival. Our headline concert has been delayed because one of the main microphones failed during the final rehearsal. Our technicians are working on the problem, but we do not yet have a reliable starting time. In the meantime, a visiting guitarist has offered to play an unplugged set near the craft market. You may also join the poetry workshop behind the café. Please keep your entrance wristband because it will be checked again when the main stage opens. Thank you for your patience, and we hope you enjoy the spontaneous performances while we make the necessary repairs.", listeningQuestion:"Which activity was arranged unexpectedly?", listeningOptions:<String>["An acoustic set near the market","A scheduled fireworks display","An early closing ceremony"], listeningAnswer:0, readingQuestion:"How did Tessa manage the unexpected delay?", readingOptions:<String>["By canceling the festival","By offering other attractions during repairs","By sending everyone home"], readingAnswer:1, writingCue:"The musicians practised at a ____ before the festival.", writingAnswer:"rehearsal"),
    EnglishAdvancedLesson(level:"B2", number:2, title:"The Hybrid Work Question", titleArabic:"جدل العمل المرن", storyTitle:"The Hybrid Work Question", storyTitleArabic:"جدل العمل المرن", paragraphs:<String>["A medium-sized company introduced hybrid work after many employees requested greater flexibility. Managers anticipated higher productivity and lower commuting costs, but some staff feared that prolonged remote work might undermine teamwork and leave new recruits isolated.","Six months later, a staff survey showed a complicated picture. Experienced workers appreciated the autonomy, whereas junior employees reported difficulties finding mentors. The results suggested that a single arrangement would not necessarily suit every department.","The management team organized a consultation and proposed regular in-person collaboration days. Several employees argued that compulsory attendance would reduce the advantages of flexibility. Others pointed out that informal conversations often generated ideas that scheduled online meetings rarely produced.","Rather than declaring the experiment a success or failure, the company adopted a revised policy that combined optional remote days with structured mentoring. The decision acknowledged a trade-off: flexibility could support well-being, provided that organizations invested in deliberate communication and fair opportunities for advancement."], storyWords:<EnglishAdvancedWord>[EnglishAdvancedWord("hybrid work","هجين بين المنزل والمكتب"),EnglishAdvancedWord("employees","موظفون"),EnglishAdvancedWord("flexibility","مرونة"),EnglishAdvancedWord("productivity","إنتاجية"),EnglishAdvancedWord("commuting costs","تكاليف التنقل"),EnglishAdvancedWord("remote work","عمل عن بعد"),EnglishAdvancedWord("teamwork","عمل جماعي"),EnglishAdvancedWord("isolated","معزول"),EnglishAdvancedWord("staff survey","استبيان الموظفين"),EnglishAdvancedWord("autonomy","استقلالية"),EnglishAdvancedWord("mentors","مرشدون"),EnglishAdvancedWord("department","قسم"),EnglishAdvancedWord("compulsory attendance","حضور إلزامي"),EnglishAdvancedWord("advancement","تقدم وظيفي")], extraWords:<EnglishAdvancedWord>[EnglishAdvancedWord("work-life balance","توازن العمل والحياة"),EnglishAdvancedWord("employee retention","الاحتفاظ بالموظفين"),EnglishAdvancedWord("burnout","إنهاك مهني"),EnglishAdvancedWord("asynchronous communication","تواصل غير متزامن"),EnglishAdvancedWord("virtual onboarding","تهيئة وظيفية افتراضية"),EnglishAdvancedWord("collaborative software","برمجيات تعاونية"),EnglishAdvancedWord("performance metrics","مؤشرات أداء"),EnglishAdvancedWord("workforce diversity","تنوع القوى العاملة"),EnglishAdvancedWord("psychological safety","أمان نفسي"),EnglishAdvancedWord("operational efficiency","كفاءة تشغيلية"),EnglishAdvancedWord("managerial discretion","تقدير إداري"),EnglishAdvancedWord("office utilization","استخدام المكاتب"),EnglishAdvancedWord("professional development","تطور مهني"),EnglishAdvancedWord("workplace culture","ثقافة العمل"),EnglishAdvancedWord("career progression","مسار الترقّي"),EnglishAdvancedWord("distributed teams","فرق موزعة"),EnglishAdvancedWord("employee engagement","اندماج الموظفين"),EnglishAdvancedWord("flexible arrangement","ترتيب مرن"),EnglishAdvancedWord("fair treatment","معاملة عادلة"),EnglishAdvancedWord("digital fatigue","إرهاق رقمي"),EnglishAdvancedWord("informal learning","تعلم غير رسمي"),EnglishAdvancedWord("team cohesion","تماسك الفريق")], grammarTitle:"Mixed conditionals and qualified recommendations", grammarArabic:"يمكننا استخدام الجمل الشرطية لتوضيح أثر قرار سابق على الوضع الحالي: If the company had invested in mentoring, new employees would feel less isolated now. كما تستخدم could وmight لعرض توصيات دون مبالغة في اليقين.", grammarExamples:<String>["If we had offered mentoring, staff would feel more supported now.","Remote work may improve focus, provided that teams communicate clearly.","A flexible policy could help, although it would require evaluation."], listening:"The human resources committee has reviewed the second employee survey on hybrid working arrangements. Its central finding is not that employees prefer to work remotely at all times, but that preferences differ considerably by role, seniority and personal circumstances. Staff with long-established professional networks generally reported higher satisfaction, while new colleagues struggled to obtain informal guidance. The committee therefore recommends scheduled mentoring sessions and voluntary team days, rather than a rigid universal attendance requirement. However, it warns that managers must monitor whether employees working mostly from home receive comparable access to promotion opportunities. A policy that improves convenience but reduces fairness would not constitute a sustainable solution. The next review will compare retention, performance and employee experiences across departments before any permanent decision is made.", listeningQuestion:"What fairness risk does the committee specifically highlight?", listeningOptions:<String>["Unequal access to promotion","Different prices for office lunches","Unreliable electricity in every home"], listeningAnswer:0, readingQuestion:"Why was the original hybrid working arrangement revised?", readingOptions:<String>["The company decided nobody should work remotely","Staff needs differed and mentoring was inadequate","All employees demanded identical hours"], readingAnswer:1, writingCue:"The survey found that employees valued greater ____ in their schedules.", writingAnswer:"flexibility"),
    EnglishAdvancedLesson(level:"C1", number:2, title:"Beneath the Changing Reef", titleArabic:"تحت الشعاب المتغيرة", storyTitle:"Beneath the Changing Reef", storyTitleArabic:"تحت الشعاب المتغيرة", paragraphs:<String>["The marine research vessel anchored beyond a stretch of coral reef that had once been celebrated for its biodiversity. Dr. Imani, an oceanographer, was leading a multidisciplinary expedition to assess the effects of unusually warm currents. Recent satellite observations suggested extensive coral bleaching, but the team needed measurements from the seabed before drawing firm conclusions.","On the first dive, a marine biologist documented patches of pale coral alongside colonies that appeared comparatively resilient. The contrast raised an intriguing question: had the surviving organisms adapted to local changes in salinity, or were they simply benefiting from temporary shelter beneath a rocky ridge? The researchers recorded water temperatures at multiple depths to distinguish those possibilities.","Analysis aboard the vessel revealed a troubling pattern. Although some sections retained vibrant fish populations, the broader ecosystem was showing signs of degradation. Local fishing communities had also noticed alterations in spawning seasons, and their observations offered a valuable complement to the scientific sampling.","The expedition faced a methodological challenge when one sensor malfunctioned. A less cautious team might have filled the missing data through broad assumptions, but Imani insisted that uncertainty should be stated explicitly. She arranged a second sampling session and invited a coastal ecologist to review the provisional findings independently.","The final briefing resisted both despair and easy optimism. Restoration measures could improve conditions in carefully selected locations, yet no local intervention could fully offset prolonged ocean warming. By combining rigorous fieldwork with community knowledge, the scientists proposed a monitoring strategy designed to reveal not only what had changed, but which responses were most likely to endure."], storyWords:<EnglishAdvancedWord>[EnglishAdvancedWord("research vessel","سفينة أبحاث"),EnglishAdvancedWord("coral reef","شعاب مرجانية"),EnglishAdvancedWord("biodiversity","تنوع حيوي"),EnglishAdvancedWord("oceanographer","عالِم محيطات"),EnglishAdvancedWord("expedition","بعثة علمية"),EnglishAdvancedWord("currents","تيارات مائية"),EnglishAdvancedWord("coral bleaching","ابيضاض المرجان"),EnglishAdvancedWord("seabed","قاع البحر"),EnglishAdvancedWord("marine biologist","عالِم أحياء بحرية"),EnglishAdvancedWord("resilient","قادر على التكيف والصمود"),EnglishAdvancedWord("salinity","ملوحة"),EnglishAdvancedWord("ecosystem","نظام بيئي"),EnglishAdvancedWord("degradation","تدهور بيئي"),EnglishAdvancedWord("spawning seasons","مواسم التكاثر"),EnglishAdvancedWord("sampling","أخذ عينات"),EnglishAdvancedWord("sensor","مستشعر")], extraWords:<EnglishAdvancedWord>[EnglishAdvancedWord("marine habitat","موئل بحري"),EnglishAdvancedWord("ocean acidification","تحمض المحيطات"),EnglishAdvancedWord("thermal stress","إجهاد حراري"),EnglishAdvancedWord("carbon sink","مصب كربون"),EnglishAdvancedWord("ecological baseline","خط أساس بيئي"),EnglishAdvancedWord("field survey","مسح ميداني"),EnglishAdvancedWord("species distribution","توزع الأنواع"),EnglishAdvancedWord("coastal erosion","تآكل الساحل"),EnglishAdvancedWord("research protocol","بروتوكول بحث"),EnglishAdvancedWord("scientific calibration","معايرة علمية"),EnglishAdvancedWord("data integrity","سلامة البيانات"),EnglishAdvancedWord("longitudinal study","دراسة طولية"),EnglishAdvancedWord("remote sensing","استشعار عن بعد"),EnglishAdvancedWord("climate variability","تقلب مناخي"),EnglishAdvancedWord("habitat fragmentation","تجزؤ الموائل"),EnglishAdvancedWord("adaptive capacity","قدرة تكيف"),EnglishAdvancedWord("ecological recovery","تعافٍ بيئي"),EnglishAdvancedWord("environmental stewardship","رعاية بيئية مسؤولة"),EnglishAdvancedWord("submerged ridge","حيد مغمور"),EnglishAdvancedWord("protected reserve","محمية"),EnglishAdvancedWord("restoration ecology","بيئة الاستعادة"),EnglishAdvancedWord("ocean warming","احترار المحيط"),EnglishAdvancedWord("species richness","غنى الأنواع"),EnglishAdvancedWord("habitat connectivity","اتصال الموائل"),EnglishAdvancedWord("underwater transect","مسار مسح تحت الماء"),EnglishAdvancedWord("reef monitoring","مراقبة الشعاب")], grammarTitle:"Academic caution and evidence synthesis", grammarArabic:"في C1 نجمع بين البيانات والتحفظ المنهجي: The results appear to indicate ... و It remains uncertain whether ... . نستخدم whereas للمقابلة بين تفسيرين، و not only ... but also لربط جوانب الدليل دون المبالغة في النتائج.", grammarExamples:<String>["The surviving coral appears to tolerate warmer water.","It remains uncertain whether these changes will persist.","The study offers not only measurements but also local observations."], listening:"At the coastal science symposium, Dr. Imani explained why an apparent reduction in coral bleaching at one site should not automatically be interpreted as ecological recovery. Some colonies had survived the recent heatwave, yet surveys showed substantial losses in other species that depend on the same reef system. The team had initially considered salinity differences as a possible explanation, but additional sampling suggested that shelter from strong currents might be more important. Even this interpretation remained provisional because the monitoring period was relatively short. Imani warned that policy makers often seek a single headline figure when evaluating habitat restoration, whereas ecological resilience involves multiple interacting processes. She advocated continued temperature logging, transparent reporting of equipment failures and closer collaboration with local fishing communities. In her view, research becomes most useful when its limitations are communicated alongside its practical implications.", listeningQuestion:"Why does Dr. Imani caution against calling the reef recovered?", listeningOptions:<String>["There are no fish anywhere","Coral survival alone does not show whole-ecosystem recovery","Salinity measurements are forbidden"], listeningAnswer:1, readingQuestion:"Why did the team arrange a second sampling session?", readingOptions:<String>["A sensor malfunction created uncertainty","The vessel had lost its anchor","The scientists wanted to avoid interviewing fishers"], readingAnswer:0, writingCue:"The reef's variety of species is known as ____. ", writingAnswer:"biodiversity"),
    EnglishAdvancedLesson(level:"C2", number:2, title:"The Translator's Unfinished Sentence", titleArabic:"الجملة التي لم يكملها المترجم", storyTitle:"The Translator's Unfinished Sentence", storyTitleArabic:"الجملة التي لم يكملها المترجم", paragraphs:<String>["When the celebrated novel was commissioned for a new edition, its translator inherited a text whose apparent simplicity concealed a formidable interpretive puzzle. One recurring idiom could signify affection, dismissal or reluctant admiration, depending on the speaker's register. The publisher wanted fluent prose, but fluency alone risked erasing the very tension that gave the original passage its force.","In the opening chapters, the translator noticed a deliberate cadence that resisted literal reproduction. An allusion to a folk song seemed innocent until it was juxtaposed with the narrator's account of exile. The phrase's polysemy forced the translator to weigh competing readings, none of which could be fully preserved through a single lexical choice.","An editor proposed an elegant paraphrase that clarified the plot but flattened the syntactic ambiguity. The translator hesitated. If the authorial intention had been to leave responsibility uncertain, then explaining away that uncertainty would not be fidelity; it would amount to an unacknowledged act of interpretation. Yet excessive literalism might equally betray the novel by making its natural voice sound contrived.","The problem became sharper when an annotated manuscript revealed revisions that the first printed edition had suppressed. Each crossed-out sentence carried a faint semantic residue, as though the author's abandoned possibilities were still audible beneath the final line. A scholar suggested that the translator treat the revisions as a kind of palimpsest rather than as disposable drafts.","At a seminar, critics offered incompatible accounts of what responsible translation required. One defended meticulous exegesis, while another invoked the discipline of hermeneutics to argue that every rendering is shaped by the reader's historical position. The translator accepted that neutrality was unattainable but rejected the cynical conclusion that accuracy therefore had no meaning. Choices could still be justified through attention to evidence, pragmatics and cultural context.","In the finished edition, the disputed idiom remained deliberately open, supported by a discreet note rather than a definitive gloss. Some reviewers praised the restraint; others found it evasive. The translator recognized the paradox: an unfinished sentence might communicate more faithfully than a perfectly polished explanation, precisely because it allowed the reader to confront the uncertainty that the original author had chosen not to resolve."], storyWords:<EnglishAdvancedWord>[EnglishAdvancedWord("translator","مترجم أدبي"),EnglishAdvancedWord("idiom","تعبير اصطلاحي"),EnglishAdvancedWord("register","مستوى الأسلوب"),EnglishAdvancedWord("cadence","إيقاع النثر"),EnglishAdvancedWord("allusion","تلميح ثقافي"),EnglishAdvancedWord("polysemy","تعدد المعاني"),EnglishAdvancedWord("lexical choice","اختيار مفرداتي"),EnglishAdvancedWord("syntactic ambiguity","لبس نحوي"),EnglishAdvancedWord("authorial intention","قصد المؤلف"),EnglishAdvancedWord("fidelity","أمانة الترجمة"),EnglishAdvancedWord("literalism","التمسك الحرفي"),EnglishAdvancedWord("semantic residue","أثر دلالي باقٍ"),EnglishAdvancedWord("palimpsest","نص تتراكب عليه آثار سابقة"),EnglishAdvancedWord("exegesis","تفسير نقدي دقيق"),EnglishAdvancedWord("hermeneutics","علم التأويل"),EnglishAdvancedWord("pragmatics","تداوليات اللغة"),EnglishAdvancedWord("gloss","شرح موجز"),EnglishAdvancedWord("paraphrase","إعادة صياغة")], extraWords:<EnglishAdvancedWord>[EnglishAdvancedWord("untranslatability","تعذر النقل الحرفي الكامل"),EnglishAdvancedWord("interpretive latitude","هامش التأويل"),EnglishAdvancedWord("textual variants","اختلافات نسخ النص"),EnglishAdvancedWord("idiomatic fluency","طلاقة تعبير اصطلاحي"),EnglishAdvancedWord("semantic drift","انزياح دلالي"),EnglishAdvancedWord("intertextuality","تناص"),EnglishAdvancedWord("cultural referent","مرجع ثقافي"),EnglishAdvancedWord("discourse marker","أداة ربط خطابية"),EnglishAdvancedWord("stylistic economy","اقتصاد أسلوبي"),EnglishAdvancedWord("translational equivalence","تكافؤ ترجمي"),EnglishAdvancedWord("narratorial voice","صوت الراوي"),EnglishAdvancedWord("philological rigor","دقة فقه اللغة"),EnglishAdvancedWord("semantic indeterminacy","عدم حسم دلالي"),EnglishAdvancedWord("focalization","تبئير سردي"),EnglishAdvancedWord("metrical pattern","نمط وزني"),EnglishAdvancedWord("unmarked construction","تركيب غير موسوم"),EnglishAdvancedWord("literary mediation","وساطة أدبية"),EnglishAdvancedWord("diachronic shift","تحول عبر الزمن"),EnglishAdvancedWord("paratext","نص محيط بالمتن"),EnglishAdvancedWord("annotated edition","نسخة مشروحة"),EnglishAdvancedWord("target readership","جمهور القراء المستهدف"),EnglishAdvancedWord("source-language nuance","دقة اللغة الأصلية"),EnglishAdvancedWord("cultural asymmetry","تفاوت ثقافي"),EnglishAdvancedWord("editorial intervention","تدخل تحريري"),EnglishAdvancedWord("semantic prosody","إيحاء دلالي متكرر"),EnglishAdvancedWord("narrative ambiguity","التباس سردي"),EnglishAdvancedWord("interpretive charity","إنصاف تأويلي"),EnglishAdvancedWord("literary voice","صوت أدبي"),EnglishAdvancedWord("discursive register","سجل خطابي"),EnglishAdvancedWord("comparative poetics","شعريات مقارنة"),EnglishAdvancedWord("lexical density","كثافة مفردات"),EnglishAdvancedWord("rhetorical restraint","ضبط بلاغي")], grammarTitle:"Subjunctive stance and layered counterfactual interpretation", grammarArabic:"في C2 نستعمل الشرط المعقد والتقديم البلاغي لتوضيح البدائل: Had the translator simplified ..., the ambiguity would have vanished. ونستخدم Were ... to ... لفرضيات أدبية، مع التفريق بين epistemic stance و stylistic effect.", grammarExamples:<String>["Had the translator simplified the idiom, the uncertainty would have disappeared.","Were the sentence to be translated literally, its cadence might sound unnatural.","Not until the annotated manuscript emerged did the editor reconsider the passage."], listening:"The translator's keynote challenged the popular assumption that an effective literary translation must remove obstacles from the reader's path. Such an assumption, she argued, treats clarity as an unconditional virtue rather than as one artistic choice among several. The disputed idiom at the heart of her latest project was not merely difficult to decode; its uncertainty was structurally important to the novel's portrayal of unreliable memory. To substitute a single, unambiguous paraphrase would have provided immediate fluency while suppressing an essential feature of the narrative. She acknowledged that absolute fidelity was impossible because languages divide meaning differently and because each reader brings distinct expectations to a text. Yet this did not release translators from the obligation to justify their decisions. On the contrary, the absence of perfect equivalence made careful attention to rhythm, syntax and cultural allusion even more important. When an audience member suggested that explanatory notes might destroy the illusion of natural storytelling, she agreed that excessive annotation could become intrusive. Her preference was therefore for a sparing paratext that disclosed only those interpretive tensions a reader could not otherwise reasonably infer. The translator concluded with a deliberately provocative claim: sometimes the most responsible version of a sentence is the one that preserves the reader's uncertainty rather than pretending to solve it.", listeningQuestion:"What does the translator regard as the main risk of replacing the idiom with one clear paraphrase?", listeningOptions:<String>["It might weaken a narratively important ambiguity","It would make the entire novel impossible to print","It would necessarily violate copyright"], listeningAnswer:0, readingQuestion:"Why did the translator retain an open-ended expression in the final edition?", readingOptions:<String>["To avoid any editing work","To preserve meaningful uncertainty from the original","Because no bilingual reviewers were available"], readingAnswer:1, writingCue:"A word or phrase with multiple related meanings shows ____. ", writingAnswer:"polysemy")
  ];
}
